export const GLOSSARY_SHARD = Object.freeze({"proof-of-stake":{"slug":"proof-of-stake","cat":"basics","en":"Proof of stake (PoS)","contentLocale":"tr","term":"Hisse ispatı (Proof of Stake, PoS)","aka":["PoS","proof of stake","pay ispatı"],"short":"Hisse ispatı (Proof of Stake, PoS), yeni blokları üretme ve doğrulama hakkının, ağın coinini teminat olarak kilitleyen (stake eden) validatörlere verildiği bir blockchain uzlaşma mekanizmasıdır.","body":[["İş ispatında güvenlik elektrik ve donanımla sağlanırken hisse ispatında sermaye ile sağlanır. Validatörler coinlerini ağa kilitler; protokol, blok önerecek validatörü genellikle stake miktarını da dikkate alan bir seçimle belirler. Dürüst çalışan ",["validatör","validator"]," ödül kazanır."],"Kurallara aykırı davranan, örneğin aynı anda iki farklı bloğu imzalayan validatörün stake'inin bir kısmı kesilir; buna slashing denir. Uzun süre çevrimdışı kalmak da küçük cezalar doğurabilir. Bu sistem, saldırıyı pahalı hale getirir çünkü saldırgan kendi kilitli parasını riske atar.",[["Ethereum","ethereum"]," Eylül 2022'deki Merge ile PoS'a geçti; Solana, Cardano ve Avalanche gibi ağlar da farklı PoS türleri kullanır. Sıradan kullanıcılar validatör çalıştırmadan, borsaların ",["staking","staking"]," ürünleri veya ",["likit staking","liquid-staking"]," protokolleri aracılığıyla da sürece katılabilir. Ödül oranları ve kilit süreleri ağdan ağa değişir."]],"example":"Bir PoS ağında toplam 10 milyon coin stake edildiğini ve yıllık ağ ödüllerinin 400.000 coin olduğunu varsayalım. Ödüller stake oranına göre dağıtılırsa yıllık getiri 400.000 / 10.000.000 = yaklaşık yüzde 4'tür. 500 coin stake ettiyseniz yılda yaklaşık 20 coin kazanırsınız. Ancak validatör hizmeti yüzde 10 komisyon alıyorsa net kazancınız 18 coine iner. Coinin fiyatı yıl içinde yüzde 15 düşerse, ek coinlere rağmen toplam değeriniz azalabilir.","mistakes":["Staking ödülünü sabit ve risksiz bir faiz gibi görmek; ödül coin cinsindendir ve fiyat değişebilir.","Kilit açma (unstaking) süresini kontrol etmeden stake edip acil ihtiyaçta paraya ulaşamamak.","Validatör veya hizmet sağlayıcıyı seçerken komisyon ve slashing geçmişine bakmamak."],"faq":[{"q":"Proof of Stake güvenli mi?","a":"Büyük PoS ağlarında saldırı, saldırganın çok büyük miktarda coin edinip riske atmasını gerektirir. Güvenlik, stake'in ne kadar dağınık olduğuna ve protokolün ceza kurallarına bağlıdır."},{"q":"PoS'ta madencilik var mı?","a":"Hayır. PoS ağlarında madenci yerine validatörler vardır ve bloklar hesaplama yarışıyla değil, stake edilen coinlere dayalı seçimle üretilir."}],"title":"Proof of Stake (PoS) nedir? Hisse ispatı nasıl çalışır?","description":"Hisse ispatının nasıl çalıştığını, validatörlerin rolünü, slashing cezasını ve staking ödüllerinin nereden geldiğini öğrenin.","related":[["staking","Staking (stake etme)","Staking, hisse kanıtı (proof of stake) kullanan bir blokzincirde coinlerinizi ağın güvenliği ve blok doğrulaması için kilitleyip karşılığında ağ ödülü almanızdır."],["liquid-staking","Likit staking (liquid staking)","Likit staking, coinlerinizi stake ederken karşılığında stake edilen pozisyonu temsil eden ve alınıp satılabilen bir token (örneğin stETH) almanızı sağlayan staking yöntemidir."],["proof-of-work","İş ispatı (Proof of Work, PoW)","İş ispatı (Proof of Work, PoW), madencilerin zor bir matematik bulmacasını çözmek için bilgi işlem gücü harcadığı ve bulmacayı ilk çözenin yeni bloğu ekleyip ödül kazandığı bir blockchain uzlaşma mekanizmasıdır."],["validator","Validatör (doğrulayıcı)","Validatör (doğrulayıcı), hisse ispatı kullanan bir blockchain'de coin stake ederek yeni blokları öneren, diğer blokları doğrulayan ve bu iş karşılığında ödül alan düğüm operatörüdür."],["ethereum","Ethereum (ETH)","Ethereum, akıllı kontratların çalıştırılabildiği programlanabilir bir blockchain'dir; yerel coini Ether (ETH) hem işlem ücretlerini (gas) ödemek hem de ağı hisse ispatıyla güvence altına almak için kullanılır."]],"lesson":null,"coin":{"slug":"ethereum","name":"Ethereum","symbol":"ETH"},"tool":null,"cta":false},"volatility":{"slug":"volatility","cat":"basics","en":"Volatility","contentLocale":"tr","term":"Volatilite (oynaklık)","aka":["oynaklık","volatility","fiyat oynaklığı"],"short":"Volatilite (oynaklık), bir varlığın fiyatının belirli bir süre içinde ne kadar ve ne hızla dalgalandığının ölçüsüdür; yüksek volatilite büyük ve ani fiyat hareketleri demektir.","body":[["Volatilite genellikle getirilerin standart sapmasıyla ölçülür ve yıllık yüzde olarak ifade edilir. Kripto paralar, hisse senetleri ve döviz kurlarına kıyasla tarihsel olarak çok daha oynaktır. Küçük piyasa değerli ",["altcoin","altcoin"],"'ler ise genellikle ",["Bitcoin","bitcoin"],"'den de oynaktır."],"Volatilite tek başına iyi ya da kötü değildir: kazanç fırsatı da, kayıp riski de yaratır. Asıl önemli olan, pozisyon büyüklüğünüzü buna göre ayarlamaktır. Aynı tutarda risk almak için oynak bir varlıkta daha küçük pozisyon açmanız gerekir.",[["Kaldıraç","leverage"]," kullananlar için volatilite doğrudan ",["likidasyon","liquidation"]," riski demektir. Yüksek oynaklıkta zarar durdur emirleri de beklenenden kötü fiyatlardan gerçekleşebilir. ",["Stablecoin","stablecoin"],"'ler ise tam tersine, düşük oynaklık sağlamak için tasarlanmıştır."]],"example":["Günlük ortalama yüzde 2 hareket eden A coini ile günlük ortalama yüzde 6 hareket eden B coinini karşılaştırın. Her işlemde en fazla 50 ",["USDT","usdt"]," kaybetmeyi kabul ediyorsanız ve zarar durdurunuzu bir günlük ortalama hareket kadar uzağa koyuyorsanız, A'da 50 / 0,02 = 2.500 USDT'lik, B'de ise 50 / 0,06 = yaklaşık 833 USDT'lik pozisyon açabilirsiniz. B'de 10x kaldıraçla 2.500 USDT'lik pozisyon açsaydınız, yüzde 6'lık sıradan bir günlük hareket teminatın yüzde 60'ını silebilirdi."],"mistakes":["Oynak ve sakin varlıklarda aynı pozisyon büyüklüğünü kullanmak.","Yüksek volatilitede zarar durdur emrini fiyata çok yakın koyup sıradan dalgalanmalarla pozisyondan çıkmak.","Düşük volatilite dönemlerinin sonsuza dek süreceğini varsayıp kaldıracı artırmak."],"faq":[{"q":"Kripto paralar neden bu kadar volatil?","a":"Piyasa görece genç ve küçüktür, haberlere hızlı tepki verir ve 7/24 açıktır. Kaldıraçlı işlemlerin yaygınlığı ve zincirleme likidasyonlar da hareketleri büyütebilir."},{"q":"Volatilite nasıl ölçülür?","a":"En yaygın yöntem, belirli bir dönemdeki getirilerin standart sapmasıdır. Ortalama gerçek aralık (ATR) gibi göstergeler ve opsiyon piyasasındaki örtük volatilite de kullanılır."}],"title":"Volatilite nedir? Kriptoda oynaklık ne demek?","description":"Volatilitenin ne olduğunu, nasıl ölçüldüğünü ve oynak varlıklarda pozisyon büyüklüğünü ve kaldıracı nasıl ayarlamanız gerektiğini öğrenin.","related":[["leverage","Kaldıraç (Leverage)","Kaldıraç, yatırdığınız teminatın birkaç katı büyüklüğünde pozisyon açmanızı sağlayan ve hem kazancı hem kaybı aynı oranda büyüten bir işlem aracıdır."],["stop-loss","Zarar durdur (stop-loss) emri","Zarar durdur (stop-loss) emri, fiyat önceden belirlediğiniz bir tetik seviyesine ulaştığında pozisyonunuzu otomatik olarak kapatarak kaybınızı sınırlamayı amaçlayan bir emirdir."],["position-sizing","Pozisyon büyüklüğü (Position sizing)","Pozisyon büyüklüğü, bir işleme ne kadar sermaye ayıracağınızı zarar durdur seviyenize ve kabul edebileceğiniz en yüksek kayba göre belirleme yöntemidir."],["stablecoin","Stablecoin (sabit coin)","Stablecoin, değerini genellikle ABD doları gibi bir referans varlığa sabitlemeyi amaçlayan ve kripto piyasasında nakit gibi kullanılan bir kripto paradır."],["liquidation","Likidasyon (Tasfiye)","Likidasyon (tasfiye), kaldıraçlı bir pozisyonun teminatı bakım seviyesinin altına düştüğünde borsanın pozisyonu zorla kapatmasıdır."]],"lesson":null,"coin":null,"tool":"/liquidations","cta":false},"stop-limit-order":{"slug":"stop-limit-order","cat":"trading","en":"Stop-limit order","contentLocale":"tr","term":"Stop-limit emir","aka":["stop limit","stop-limit order","stop limit emri"],"short":"Stop-limit emir, fiyat belirlediğiniz tetik (stop) seviyesine ulaştığında, önceden tanımladığınız fiyattan bir limit emir gönderen ve böylece kötü fiyattan dolmayı engelleyen koşullu bir emirdir.","body":[["Stop-limit emirde iki fiyat girersiniz: tetik fiyatı ve limit fiyatı. Fiyat tetiğe ulaşana kadar emir defterde görünmez. Tetiklendiğinde, belirlediğiniz limit fiyatıyla normal bir ",["limit emir","limit-order"]," oluşur ve o fiyattan veya daha iyisinden dolmayı bekler."],"Avantajı fiyat kontrolüdür: hiçbir koşulda limit fiyatınızdan daha kötü bir fiyattan işlem yapılmaz. Dezavantajı ise dolma garantisi olmamasıdır. Fiyat tetiği geçip limit seviyenizin de altına hızla düşerse emir defterde bekler ve pozisyonunuz açık kalır.","Bu riski azaltmak için satışta limit fiyatını tetik fiyatının biraz altına koymak yaygındır; aradaki boşluk, ne kadar kaymaya razı olduğunuzu gösterir. Kırılım stratejilerinde stop-limit alış emri, fiyat belirli bir direnci geçince alım yapmak için de kullanılır."],"example":["Elinizde 10 coin var, fiyat 50 ",["USDT","usdt"],". Tetik 46 USDT, limit 45,5 USDT olan bir stop-limit satış emri koyuyorsunuz. Fiyat yavaşça düşüp 46'ya gelirse 45,5 veya daha iyi fiyattan bir satış emri oluşur ve büyük olasılıkla dolar; en kötü durumda 455 USDT alırsınız. Ancak kötü bir haberle fiyat bir anda 47'den 43'e atlarsa emriniz tetiklenir ama 45,5'ten alıcı bulunmadığı için dolmaz. Pozisyonunuz açık kalır ve değeri 430 USDT'ye iner; fiyat düşmeye devam ederse kayıp da büyür."],"mistakes":["Limit fiyatını tetik fiyatıyla tamamen aynı yapıp hızlı hareketlerde emrin dolmamasına yol açmak.","Stop-limit emri koyduktan sonra pozisyonun kesinlikle korunduğunu varsaymak.","Satış emrinde tetik ve limit fiyatlarını ters girip emrin anında veya beklenmedik şekilde çalışmasına neden olmak."],"faq":[{"q":"Stop-limit ile stop-market arasındaki fark nedir?","a":"Stop-limit tetiklendiğinde limit emir gönderir ve fiyat garantisi verir ama dolmayabilir. Stop-market ise piyasa emri gönderir ve dolar ama fiyatı garanti değildir."},{"q":"Stop-limitte limit fiyatı nasıl seçilir?","a":"Satış için genellikle tetik fiyatının biraz altına, alış için biraz üstüne konur. Boşluk ne kadar büyükse dolma olasılığı o kadar artar ama kabul ettiğiniz en kötü fiyat da kötüleşir."}],"title":"Stop-limit emir nedir? Nasıl çalışır?","description":"Stop-limit emrin tetik ve limit fiyatıyla nasıl çalıştığını, stop-market'ten farkını ve neden dolmayabileceğini öğrenin.","related":[["stop-loss","Zarar durdur (stop-loss) emri","Zarar durdur (stop-loss) emri, fiyat önceden belirlediğiniz bir tetik seviyesine ulaştığında pozisyonunuzu otomatik olarak kapatarak kaybınızı sınırlamayı amaçlayan bir emirdir."],["limit-order","Limit emir (limit order)","Limit emir (limit order), yalnızca belirlediğiniz fiyattan veya daha iyisinden gerçekleşen, piyasa o fiyata gelene kadar emir defterinde bekleyen alım ya da satım emridir."],["slippage","Kayma (slippage)","Kayma (slippage), bir emrin beklenen fiyat ile gerçekte gerçekleştiği ortalama fiyat arasındaki farktır ve genellikle piyasa emirlerinde, düşük likiditede veya hızlı fiyat hareketlerinde ortaya çıkar."],["trailing-stop","İz süren stop (trailing stop)","İz süren stop (trailing stop), fiyat lehinize hareket ettikçe tetik seviyesini otomatik olarak belirli bir yüzde veya tutar kadar geriden takip ettiren, fiyat geri döndüğünde ise pozisyonu kapatan bir emirdir."]],"lesson":{"id":"E17","slug":"stop-loss-is-a-plan","ep":17,"title":"Kâr al ve zarar durdur plandır, sigorta değil"},"coin":null,"tool":null,"cta":false},"time-in-force":{"slug":"time-in-force","cat":"trading","en":"Time in force (GTC, IOC, FOK)","contentLocale":"tr","term":"Emir geçerlilik süresi (GTC, IOC, FOK)","aka":["time in force","GTC","IOC","FOK"],"short":"Emir geçerlilik süresi (time in force), bir emrin ne kadar süre aktif kalacağını ve dolmayan kısmına ne olacağını belirleyen ayardır; en yaygın seçenekler GTC, IOC ve FOK'tur.","body":["GTC (Good Till Cancelled), iptal edilene kadar geçerli demektir: emir siz iptal edene veya tamamen dolana kadar defterde bekler. Çoğu borsada limit emirlerin varsayılan ayarıdır. Bazı borsalar çok uzun süre bekleyen emirleri belirli bir sürenin sonunda otomatik iptal edebilir.","IOC (Immediate or Cancel), hemen gerçekleş ya da iptal et anlamına gelir: emrin o anda dolabilen kısmı gerçekleşir, kalan kısım anında iptal edilir. FOK (Fill or Kill) ise ya tamamını hemen gerçekleştir ya da hiç gerçekleştirme demektir; kısmi dolum kabul edilmez.","Bu ayarlar özellikle büyük emirlerde ve likiditenin sınırlı olduğu paritelerde önemlidir. Kısmi dolumun sorun olmadığı durumlarda IOC, belirli bir miktarın tamamına ihtiyaç duyduğunuzda FOK kullanılır. Hangi seçeneklerin sunulduğu ve adları borsadan borsaya değişir."],"example":["Bir paritede 25,00 ",["USDT","usdt"],"'de yalnızca 300 coinlik satış emri var, bir üst seviye 25,10. Siz 25,00'dan 500 coinlik limit alış emri veriyorsunuz. GTC seçerseniz 300 coin hemen dolar, kalan 200 coinlik emir defterde bekler. IOC seçerseniz 300 coin 7.500 USDT'ye dolar ve kalan 200 coinlik kısım iptal edilir. FOK seçerseniz, 25,00'da 500 coinin tamamı bulunmadığı için emrin hiçbir kısmı gerçekleşmez ve emir tamamen iptal edilir."],"mistakes":["GTC emirleri defterde unutup haftalar sonra beklenmedik bir anda dolmalarına izin vermek.","FOK seçip likiditenin yetersiz olduğu paritede emrin neden hiç dolmadığını anlamamak.","IOC ile verilen emrin kalan kısmının defterde beklediğini sanmak."],"faq":[{"q":"GTC ne demek?","a":"Good Till Cancelled, yani iptal edilene kadar geçerli anlamına gelir. Emir siz iptal edene veya tamamen dolana kadar emir defterinde kalır."},{"q":"IOC ile FOK arasındaki fark nedir?","a":"IOC'de emrin hemen dolabilen kısmı gerçekleşir ve kalanı iptal edilir. FOK'ta ise emir ya tamamen hemen dolar ya da hiç dolmaz."}],"title":"GTC, IOC, FOK nedir? Emir geçerlilik süresi","description":"GTC, IOC ve FOK emir geçerlilik seçeneklerinin farkını ve kısmi dolumda emrinize ne olduğunu örnekle öğrenin.","related":[["limit-order","Limit emir (limit order)","Limit emir (limit order), yalnızca belirlediğiniz fiyattan veya daha iyisinden gerçekleşen, piyasa o fiyata gelene kadar emir defterinde bekleyen alım ya da satım emridir."],["post-only-order","Sadece yapıcı (post-only) emir","Sadece yapıcı (post-only) emir, yalnızca emir defterine eklenebiliyorsa kabul edilen ve anında eşleşip taker olacaksa iptal edilen bir limit emir seçeneğidir; amacı her zaman maker ücreti ödemektir."],["market-order","Piyasa emri (market order)","Piyasa emri (market order), fiyat belirtmeden verilen ve emir defterindeki en iyi mevcut fiyatlardan hemen gerçekleşen alım veya satım emridir."],["order-book","Emir defteri (order book)","Emir defteri (order book), bir paritede bekleyen tüm alış ve satış limit emirlerinin fiyat seviyelerine ve miktarlarına göre sıralandığı, borsanın gerçek zamanlı listesidir."]],"lesson":{"id":"E14","slug":"market-limit-cancel","ep":14,"title":"Piyasa, limit, iptal: Her biri neyi çözer?"},"coin":null,"tool":null,"cta":false},"private-key":{"slug":"private-key","cat":"wallets-security","en":"Private key","contentLocale":"tr","term":"Özel anahtar (private key)","aka":["private key","gizli anahtar"],"short":"Özel anahtar, bir kripto adresindeki varlıkları harcamak için gereken dijital imzayı üreten gizli bir sayıdır ve onu bilen kişi o adresin fiilî sahibi olur.","body":[["Her ",["kripto adresi","wallet-address"]," bir anahtar çiftine dayanır: özel anahtar ve ondan türetilen ",["açık anahtar","public-key"],". Bir işlem gönderdiğinizde cüzdan, işlemi özel anahtarla imzalar. Ağdaki düğümler bu imzayı açık anahtarla doğrular, ancak imzadan özel anahtarı geri çıkaramaz."],["Pratikte özel anahtar uzun bir onaltılık sayı olarak görünür. Çoğu modern cüzdan size tek tek özel anahtar göstermek yerine bir ",["kurtarma ifadesi","seed-phrase"]," verir; tüm özel anahtarlar bu ifadeden türetilir. Bazı cüzdanlar tek bir hesabın özel anahtarını dışa aktarma seçeneği de sunar."],"Borsada tuttuğunuz varlıkların özel anahtarları borsadadır. Bu nedenle kriptoda sık duyulan \"anahtarlar sizde değilse coinler de sizin değildir\" sözü, saklama riskini anlatır. Özel anahtarınız sızarsa yapılacak tek doğru şey, fonları hemen yeni ve temiz bir cüzdana taşımaktır."],"example":["Bir adreste 3.000 ",["USDC","usdc"]," ve 0,05 ",["ETH","ethereum"]," (ağ ücretleri için) tuttuğunuzu varsayalım. Bir \"cüzdan kurtarma\" sitesine yanlışlıkla bu hesabın özel anahtarını yapıştırdınız. Saldırganlar genellikle otomatik botlarla izler ve fonları dakikalar içinde boşaltabilir. Fark ettiğiniz anda yeni bir cüzdan açıp 3.000 USDC'yi oraya gönderirseniz ve ",["ağ ücreti","gas-fee"]," 0,002 ETH tutarsa, eski adreste 0,048 ETH kalır; o adresi bir daha kullanmamanız gerekir."],"mistakes":["Özel anahtarı \"teknik destek\" bahanesiyle birine göndermek.","Özel anahtarı tarayıcıya veya güvenilmeyen bir araca yapıştırmak.","Sızan bir anahtarın adresini kullanmaya devam etmek."],"faq":[{"q":"Özel anahtardan adres bulunabilir mi?","a":"Evet, özel anahtardan açık anahtar ve adres hesaplanabilir. Tersi ise pratikte imkânsızdır; adresten özel anahtar bulunamaz."},{"q":"Borsa hesabımın özel anahtarı var mı?","a":"Borsa hesabınızdaki varlıkların anahtarlarını borsa yönetir; size ayrıca özel anahtar verilmez. Hesap güvenliği şifre ve iki faktörlü doğrulama ile sağlanır."}],"title":"Özel anahtar (private key) nedir? Kriptoda anlamı","description":"Özel anahtarın ne işe yaradığını, açık anahtar ve kurtarma ifadesiyle ilişkisini ve sızarsa ne yapmanız gerektiğini öğrenin.","related":[["seed-phrase","Kurtarma ifadesi (seed phrase)","Kurtarma ifadesi (seed phrase), bir kripto cüzdanının tüm özel anahtarlarının türetildiği 12 veya 24 kelimelik listedir ve bu kelimeleri bilen herkes cüzdanın tamamını kontrol edebilir."],["public-key","Açık anahtar (public key)","Açık anahtar, özel anahtardan matematiksel olarak türetilen, imzaların doğrulanmasına yarayan ve genellikle cüzdan adresinin üretilmesinde kullanılan paylaşılabilir anahtardır."],["wallet-address","Cüzdan adresi (wallet address)","Cüzdan adresi, bir blokzincirde kripto almak için paylaştığınız, açık anahtardan türetilen harf ve rakamlardan oluşan bir dizidir; banka hesap numarasına benzer ama ağa özgüdür."],["multisig-wallet","Çoklu imza cüzdanı (multisig)","Çoklu imza (multisig) cüzdanı, bir işlemin gerçekleşmesi için birden fazla özel anahtarın onayını gerektiren, örneğin 3 anahtardan 2'sinin imzasını isteyen kripto cüzdanıdır."]],"lesson":{"id":"E03","slug":"exchange-vs-wallet","ep":3,"title":"Coin'lerim nerede? Borsa ve cüzdan farkı"},"coin":null,"tool":null,"cta":false},"amm":{"slug":"amm","cat":"defi","en":"Automated market maker (AMM)","contentLocale":"tr","term":"Otomatik piyasa yapıcı (AMM)","aka":["AMM","automated market maker","otomatik piyasa yapıcı"],"short":"Otomatik piyasa yapıcı (AMM), alıcı ve satıcıları bir emir defterinde eşleştirmek yerine, likidite havuzundaki token oranlarına göre fiyatı bir formülle belirleyen ve takası doğrudan havuzla yaptıran DEX modelidir.","body":[["Klasik borsada fiyat, emir defterindeki alış ve satış emirleriyle oluşur. AMM'de ise her işlem çifti için bir havuz vardır, örneğin ",["ETH","ethereum"]," ve ",["USDC","usdc"],". Siz ETH aldığınızda havuza USDC eklenir, havuzdan ETH çıkar; havuzda ETH azaldıkça ETH'nin fiyatı yükselir."],["Uniswap'in popüler hâle getirdiği en bilinen formül x × y = k'dir: iki token miktarının çarpımı sabit kalır. Bu yüzden büyük bir işlem havuz oranını çok değiştirir ve ",["fiyat kayması","slippage"]," (slippage) artar. Derin havuzlarda aynı işlem fiyatı daha az etkiler."],["Havuza token yatıranlara ",["likidite sağlayıcı","market-maker"]," (LP) denir ve takas ücretlerinden pay alırlar. Curve gibi ",["stablecoin","stablecoin"],"'ler için optimize edilmiş AMM'ler veya Uniswap v3 gibi likiditenin belirli fiyat aralıklarına yoğunlaştırıldığı modeller de vardır. Fiyatlar dış piyasadan saptığında arbitrajcılar havuzu yeniden piyasa fiyatına çeker."]],"example":"Bir havuzda 100 ETH ve 300.000 USDC olduğunu varsayalım; k = 30.000.000 ve fiyat 3.000 USDC. Siz havuzdan 10 ETH almak istiyorsunuz. Havuzda 90 ETH kalacaksa USDC miktarı 30.000.000 / 90 = yaklaşık 333.333 olmalı. Yani yaklaşık 33.333 USDC ödersiniz; ortalama fiyat ETH başına yaklaşık 3.333 USDC olur, ücretler hariç. Aynı 10 ETH'yi 1.000 ETH'lik bir havuzdan alsaydınız kayma çok daha küçük olurdu.","mistakes":["Havuz derinliğine bakmadan büyük tutarlı takas yapmak.","Ekranda görülen fiyatın büyük işlemde de aynen geçerli olacağını sanmak.","AMM fiyatının her zaman merkezi borsa fiyatıyla aynı olduğunu varsaymak."],"faq":[{"q":"AMM ile emir defteri arasındaki fark nedir?","a":"Emir defterinde fiyat alıcı ve satıcıların emirleriyle belirlenir. AMM'de fiyat havuzdaki token oranından bir formülle hesaplanır ve karşı taraf havuzdur."},{"q":"AMM'de fiyat nasıl güncel kalır?","a":"Havuz fiyatı dış piyasadan saptığında arbitrajcılar ucuz taraftan alıp pahalı tarafa satar. Bu işlemler havuz oranını piyasa fiyatına yaklaştırır."}],"title":"AMM (otomatik piyasa yapıcı) nedir? Nasıl çalışır?","description":"Otomatik piyasa yapıcının fiyatı nasıl belirlediğini, x × y = k formülünü ve fiyat kaymasının nereden geldiğini öğrenin.","related":[["liquidity-pool","Likidite havuzu (liquidity pool)","Likidite havuzu, kullanıcıların yatırdığı iki veya daha fazla token'ın bir akıllı sözleşmede kilitlendiği ve DEX'lerde takasların doğrudan bu havuzdan yapıldığı fon havuzudur."],["impermanent-loss","Geçici kayıp (impermanent loss)","Geçici kayıp, bir likidite havuzuna yatırdığınız token'ların fiyat oranı değiştiğinde, pozisyonunuzun değerinin aynı token'ları cüzdanda tutmaya göre daha düşük kalması durumudur."],["dex","Merkeziyetsiz borsa (DEX)","Merkeziyetsiz borsa (DEX), kullanıcıların kendi cüzdanlarından, bir şirkete fon emanet etmeden, akıllı sözleşmeler aracılığıyla kripto takası yaptığı borsadır."],["slippage","Kayma (slippage)","Kayma (slippage), bir emrin beklenen fiyat ile gerçekte gerçekleştiği ortalama fiyat arasındaki farktır ve genellikle piyasa emirlerinde, düşük likiditede veya hızlı fiyat hareketlerinde ortaya çıkar."]],"lesson":null,"coin":{"slug":"uniswap","name":"Uniswap","symbol":"UNI"},"tool":null,"cta":false},"staking":{"slug":"staking","cat":"defi","en":"Staking","contentLocale":"tr","term":"Staking (stake etme)","aka":["stake etme","staking","kilitleme"],"short":"Staking, hisse kanıtı (proof of stake) kullanan bir blokzincirde coinlerinizi ağın güvenliği ve blok doğrulaması için kilitleyip karşılığında ağ ödülü almanızdır.","body":[[["Ethereum","ethereum"],", Solana, Cardano gibi proof of stake ağlarında blokları doğrulayıcılar (",["validator","validator"],") üretir. Doğrulayıcı olmak için coin stake etmek gerekir; dürüst davrananlar ödül alır, kurallara aykırı davrananlar stake'lerinin bir kısmını kaybedebilir (slashing). Bu yapı ağın güvenliğini sağlar."],["Kullanıcıların staking'e katılmasının birkaç yolu vardır: kendi doğrulayıcınızı çalıştırmak, bir doğrulayıcıya coinlerinizi delege etmek, ",["likit staking","liquid-staking"]," protokolleri kullanmak veya borsaların staking ürünlerine katılmak. Borsa staking'i en kolay yoldur, ancak varlıklarınız borsanın saklamasındadır."],"Getiri oranı ağın kurallarına, toplam stake edilen miktara ve doğrulayıcı komisyonuna göre değişir; garantili değildir. Bazı ağlarda stake'i çözmek (unstake) günler sürebilir ve bu sürede fiyat düşse bile satamazsınız. Ödüller aynı coin cinsinden geldiği için coin fiyatı düşerse dolar bazında kayıp yaşayabilirsiniz."],"example":["4 ETH stake ettiğinizi ve ağ ödülünün o dönem yıllık yaklaşık yüzde 3 olduğunu varsayalım. Bir yılda yaklaşık 0,12 ETH ödül kazanırsınız ve toplamınız 4,12 ETH olur. ETH fiyatı bu sürede 3.000 ",["USDC","usdc"],"'den 2.500 USDC'ye düşerse, başlangıçtaki 12.000 USDC'lik değeriniz 4,12 × 2.500 = 10.300 USDC olur. Ödül coin sayısını artırır, ama fiyat riskini ortadan kaldırmaz."],"mistakes":["Staking getirisinin dolar bazında garanti olduğunu sanmak.","Unstake bekleme süresini hesaba katmadan acil ihtiyaç parasını stake etmek.","Borsada stake edilen varlığın borsa riskine açık olduğunu unutmak."],"faq":[{"q":"Staking'te para kaybedilebilir mi?","a":"Evet. Coin fiyatı düşebilir, doğrulayıcı hataları nedeniyle slashing yaşanabilir veya platform riski oluşabilir. Ödül bu riskleri kapatmayabilir."},{"q":"Staking ödülleri ne zaman ödenir?","a":"Ağa ve kullanılan platforma göre değişir; bazıları her gün, bazıları belirli dönemlerde dağıtır. Platformun ürün sayfasındaki koşulları kontrol edin."}],"title":"Staking nedir? Kripto stake etme nasıl çalışır?","description":"Staking'in nasıl çalıştığını, ödüllerin nereden geldiğini, unstake sürelerini ve fiyat riskini örnekle öğrenin.","related":[["proof-of-stake","Hisse ispatı (Proof of Stake, PoS)","Hisse ispatı (Proof of Stake, PoS), yeni blokları üretme ve doğrulama hakkının, ağın coinini teminat olarak kilitleyen (stake eden) validatörlere verildiği bir blockchain uzlaşma mekanizmasıdır."],["liquid-staking","Likit staking (liquid staking)","Likit staking, coinlerinizi stake ederken karşılığında stake edilen pozisyonu temsil eden ve alınıp satılabilen bir token (örneğin stETH) almanızı sağlayan staking yöntemidir."],["validator","Validatör (doğrulayıcı)","Validatör (doğrulayıcı), hisse ispatı kullanan bir blockchain'de coin stake ederek yeni blokları öneren, diğer blokları doğrulayan ve bu iş karşılığında ödül alan düğüm operatörüdür."],["crypto-earn","Kripto kazanç ürünleri (Earn)","Kripto kazanç (Earn) ürünleri, borsaların kullanıcıların coin'lerini esnek veya vadeli olarak yatırıp karşılığında faiz benzeri getiri almasını sağlayan birikim ve getiri ürünleridir."],["apr-vs-apy","APR ve APY farkı","APR, bileşik etki olmadan hesaplanan basit yıllık getiri oranıdır; APY ise kazancın düzenli olarak yeniden yatırıldığı varsayımıyla bileşik getiriyi gösterir, bu yüzden aynı oran için APY her zaman APR'den yüksek veya ona eşittir."]],"lesson":null,"coin":{"slug":"ethereum","name":"Ethereum","symbol":"ETH"},"tool":null,"cta":true},"total-value-locked":{"slug":"total-value-locked","cat":"defi","en":"Total value locked (TVL)","contentLocale":"tr","term":"Kilitli toplam değer (TVL)","aka":["TVL","total value locked","toplam kilitli değer"],"short":"Kilitli toplam değer (TVL), bir DeFi protokolünün veya blokzincirin akıllı sözleşmelerinde yatırılmış olarak duran tüm varlıkların güncel piyasa değeridir.","body":[["TVL, ",["DeFi","defi"],"'de bir protokolün büyüklüğünü ölçmek için en çok kullanılan göstergedir. Borç verme havuzlarındaki mevduatlar, ",["DEX","dex"]," ",["likidite","liquidity"]," havuzları ve stake edilmiş varlıklar bu toplamda yer alır. DefiLlama gibi veri siteleri protokolleri ve ağları TVL'ye göre sıralar."],["TVL'yi yorumlarken dikkat gerekir. Değer dolar cinsinden hesaplandığı için, kimse para çekmese bile içerideki token'ların fiyatı düşerse TVL düşer. Ayrıca aynı varlık birden fazla protokolde katmanlı olarak kullanıldığında (örneğin ",["LST","liquid-staking"],"'nin başka bir protokolde teminat olması) toplamlar şişebilir."],"Yüksek TVL güven ve likidite işareti olabilir, ama tek başına güvenlik garantisi değildir. Geçmişte yüksek TVL'li protokoller de istismar edildi. TVL'yi işlem hacmi, ücret gelirleri, denetim geçmişi ve kullanıcı sayısıyla birlikte değerlendirmek daha sağlıklıdır."],"example":["Bir protokolde 10.000 ",["ETH","ethereum"]," ve 50 milyon ",["USDC","usdc"]," kilitli olduğunu varsayalım. ETH 3.000 USDC iken TVL = 10.000 × 3.000 + 50.000.000 = 80 milyon USDC. Ertesi hafta kimse para çekmeden ETH fiyatı yüzde 20 düşüp 2.400 USDC olursa TVL = 24 milyon + 50 milyon = 74 milyon USDC olur. TVL yüzde 7,5 düşmüş görünür, ama bu kullanıcı kaybı değil fiyat etkisidir."],"mistakes":["TVL düşüşünü her zaman kullanıcıların protokolü terk etmesi olarak yorumlamak.","Yüksek TVL'yi güvenlik denetiminin yerine koymak.","Farklı veri kaynaklarının TVL'yi farklı yöntemlerle hesapladığını göz ardı etmek."],"faq":[{"q":"TVL yüksekse protokol güvenli midir?","a":"Hayır, TVL güvenliği değil yalnızca yatırılmış değeri ölçer. Yüksek TVL saldırganlar için de daha cazip bir hedef olabilir."},{"q":"TVL ile piyasa değeri arasındaki fark nedir?","a":"Piyasa değeri bir token'ın toplam dolaşımdaki değeridir. TVL ise protokolün sözleşmelerinde yatırılmış duran varlıkların değeridir."}],"title":"TVL (kilitli toplam değer) nedir? Nasıl yorumlanır?","description":"TVL'nin ne olduğunu, fiyat hareketlerinden nasıl etkilendiğini ve bir DeFi protokolünü değerlendirirken nasıl kullanılacağını öğrenin.","related":[["defi","DeFi (merkeziyetsiz finans)","DeFi (merkeziyetsiz finans), borç verme, takas, getiri elde etme gibi finansal hizmetlerin banka veya borsa yerine blokzincirdeki akıllı sözleşmelerle sunulduğu açık uygulamalar ekosistemidir."],["liquidity-pool","Likidite havuzu (liquidity pool)","Likidite havuzu, kullanıcıların yatırdığı iki veya daha fazla token'ın bir akıllı sözleşmede kilitlendiği ve DEX'lerde takasların doğrudan bu havuzdan yapıldığı fon havuzudur."],["defi-lending","DeFi borç verme (DeFi lending)","DeFi borç verme, kullanıcıların kripto varlıklarını akıllı sözleşme havuzlarına yatırarak faiz kazandığı, başkalarının da bu havuzlardan teminat göstererek borç aldığı merkeziyetsiz kredi sistemidir."],["market-capitalization","Piyasa değeri (market cap)","Piyasa değeri (market cap), bir kripto paranın güncel fiyatının dolaşımdaki arzla çarpılmasıyla bulunan toplam değerdir ve coinlerin büyüklüğünü karşılaştırmak için kullanılır."]],"lesson":null,"coin":{"slug":"aave","name":"Aave","symbol":"AAVE"},"tool":null,"cta":false},"depeg":{"slug":"depeg","cat":"stablecoins","en":"Depeg","contentLocale":"tr","term":"Depeg (sabitin kopması)","aka":["depeg","sabitlemeden kopma","peg kaybı"],"short":"Depeg, bir stablecoin'in bağlı olduğu değerden, örneğin 1 dolardan, belirgin ve kalıcı biçimde uzaklaşmasıdır; coin artık hedef fiyatında işlem görmez.","body":[[["Stablecoin","stablecoin"],"'ler genellikle 1 ABD dolarına sabitlenir. Bu sabitlemeye İngilizcede peg denir. Fiyat 0,999 ile 1,001 arasında küçük salınımlar yapabilir; bu normaldir. Depeg ise fiyatın 0,97, 0,90 ya da daha aşağıya düşüp orada kalması, yani piyasanın coin'in gerçekten 1 dolar edeceğine olan güvenini kaybetmesidir."],["Depeg'in birkaç tipik nedeni vardır: rezervlerle ilgili şüpheler, rezervlerin tutulduğu bir bankada yaşanan sorun, teminat değerinin hızla düşmesi ya da algoritmik bir modelin çökmesi. 2023 başında bir ABD bankasının kapanmasıyla ",["USDC","usdc"]," kısa süreliğine 1 doların altına inmiş, rezervlerin güvende olduğu anlaşılınca toparlanmıştı. ",["Algoritmik stablecoin","algorithmic-stablecoin"],"'lerde ise depeg bazen kalıcı olabilir."],"Trader için önemli nokta şudur: stablecoin'i nakit gibi görmek, onun ihraççısına ve mekanizmasına güvenmek demektir. Borsada tuttuğunuz bakiyeyi birkaç farklı stablecoin'e bölmek ve fiyatı izlemek tek bir coin'e bağlı riski azaltır."],"example":"Elinizde 10.000 adet X stablecoin'i olduğunu varsayalım. Normalde bunlar 10.000 dolar eder. Bir gün rezerv haberleriyle fiyat 0,92 dolara iner. Bu durumda varlığınızın değeri 9.200 dolara düşer, yani 800 dolar kayıp görünür. Panikle satarsanız bu kaybı kesinleştirirsiniz. Fiyat daha sonra 1 dolara dönerse bekleyen kişi kaybı geri alır; dönmezse bekleyen kişi daha fazla kaybedebilir. Hangisinin olacağını rezerv yapısı belirler, bu yüzden önce sebebi anlamak gerekir.","mistakes":["Her stablecoin'in her koşulda tam 1 dolar olduğunu varsaymak.","Tüm birikimi tek bir stablecoin'de, tek bir platformda tutmak.","Kısa süreli 0,998 gibi küçük sapmaları depeg sanıp gereksiz yere işlem yapmak.","Depeg sırasında ihraççının açıklamasını okumadan dolaşan söylentilere göre satmak."],"faq":[{"q":"Depeg ne demek?","a":"Depeg, bir stablecoin'in sabitlendiği değerden, genellikle 1 dolardan, belirgin şekilde ayrılmasıdır. Küçük ve kısa süreli salınımlar depeg sayılmaz."},{"q":"Depeg olan stablecoin tekrar 1 dolara döner mi?","a":"Rezervleri gerçekten yeterli olan bir stablecoin çoğu zaman güven geri geldiğinde toparlanır. Teminatı yetersiz ya da algoritmik modeli çökmüş coin'lerde ise dönüş garanti değildir."},{"q":"USDT veya USDC depeg olabilir mi?","a":"Teorik olarak her stablecoin depeg yaşayabilir. USDC 2023'te kısa süreliğine sabitini kaybetmişti; bu yüzden ihraççının rezerv raporlarını takip etmek önemlidir."}],"title":"Depeg nedir? Stablecoin sabitini kaybedince ne olur","description":"Depeg nedir, stablecoin neden 1 dolardan kopar ve böyle bir durumda bakiyenizi nasıl değerlendirmelisiniz, örnekle öğrenin.","related":[["stablecoin","Stablecoin (sabit coin)","Stablecoin, değerini genellikle ABD doları gibi bir referans varlığa sabitlemeyi amaçlayan ve kripto piyasasında nakit gibi kullanılan bir kripto paradır."],["algorithmic-stablecoin","Algoritmik stablecoin","Algoritmik stablecoin, fiyatını tam rezerv yerine arz-talebi otomatik ayarlayan kurallar ve çoğu zaman ikinci bir token ile 1 dolarda tutmaya çalışan stablecoin türüdür."],["usdc","USDC (USD Coin)","USDC (USD Coin), Circle tarafından çıkarılan, nakit ve kısa vadeli ABD hazine bonolarıyla desteklenen ve değerini 1 ABD dolarına sabitlemeyi amaçlayan bir stablecoin'dir."],["liquid-staking","Likit staking (liquid staking)","Likit staking, coinlerinizi stake ederken karşılığında stake edilen pozisyonu temsil eden ve alınıp satılabilen bir token (örneğin stETH) almanızı sağlayan staking yöntemidir."]],"lesson":{"id":"E02","slug":"is-usdt-a-dollar","ep":2,"title":"USDT dolar mı? Kripto alırken neden her yerde karşımıza çıkar?"},"coin":{"slug":"tether","name":"Tether","symbol":"USDT"},"tool":null,"cta":false},"real-world-assets":{"slug":"real-world-assets","cat":"tokenized-assets","en":"Real-world assets (RWA)","contentLocale":"tr","term":"Gerçek dünya varlıkları (RWA)","aka":["RWA","real-world assets","gerçek dünya varlıkları","tokenize varlıklar"],"short":"Gerçek dünya varlıkları (RWA), devlet tahvilleri, altın, gayrimenkul, krediler veya hisseler gibi blockchain dışındaki varlıkların zincir üstünde token olarak temsil edilmesidir.","body":[["RWA, geleneksel finans varlıklarını ",["blockchain","blockchain"],"'e taşır. Bir ihraççı varlığı hukuki bir yapı içinde tutar ve karşılığında token çıkarır. Bilinen örnekler arasında tokenize ABD hazine bonoları, Paxos'un ",["PAXG","tokenized-gold"],"'si gibi altın token'ları ve Ondo Finance gibi projelerin ürünleri bulunur."],["Avantajları şunlardır: küçük tutarlarla bölünebilir yatırım, 7/24 transfer, ",["DeFi","defi"]," uygulamalarında teminat olarak kullanılabilme. Bu yüzden ",["stablecoin","stablecoin"]," rezervleri ve DeFi protokolleri de giderek RWA kullanıyor."],["Ama risk zincir dışındadır. Token'ın değeri ihraççının gerçekten varlığı tuttuğuna, saklayıcının güvenilirliğine ve hukuki yapının geçerliliğine bağlıdır. Birçok RWA ürünü yalnızca ",["KYC","kyc"],"'den geçmiş ve belirli ülkelerdeki yatırımcılara açıktır."]],"example":["Tokenize bir kredi havuzunun yıllık yüzde 9 getiri sunduğunu varsayalım. 2.000 ",["USDC","usdc"]," yatırırsanız bir yıl sonunda brüt 180 USDC beklersiniz. Ürün yıllık yüzde 0,5 yönetim ücreti alıyorsa 10 USDC düşülür ve net 170 USDC kalır. Ancak havuzdaki kredilerin yüzde 5'i geri ödenmezse havuz değeri de yüzde 5 kayıp yaşar: 2.000 USDC'lik payınızdan 100 USDC eksilir ve net kazancınız 70 USDC'ye düşer. Getiri, alttaki varlığın gerçek performansına bağlıdır."],"mistakes":["RWA token'ının tamamen risksiz olduğunu, çünkü arkasında gerçek varlık olduğunu varsaymak.","İhraççının hukuki yapısını, saklayıcısını ve denetim raporlarını kontrol etmemek.","Ürünün ülkenizdeki yatırımcılara açık olup olmadığına bakmamak."],"faq":[{"q":"RWA ne demek?","a":"RWA, Real-World Assets yani gerçek dünya varlıkları demektir. Tahvil, altın, gayrimenkul gibi varlıkların blockchain üzerinde token olarak temsil edilmesini ifade eder."},{"q":"RWA token'ları nasıl alınır?","a":"Bazıları borsalarda veya DEX'lerde işlem görür, bazıları ise yalnızca ihraççının platformunda KYC ile alınabilir. Erişim ürüne ve ülkenize göre değişir."}],"title":"RWA nedir? Gerçek dünya varlıklarının tokenizasyonu","description":"RWA (gerçek dünya varlıkları) nedir, tahvil, altın ve kredi gibi varlıklar nasıl token'a dönüşür ve hangi riskleri taşır.","related":[["tokenized-treasuries","Tokenize hazine bonoları","Tokenize hazine bonoları, ABD Hazine bonosu gibi kısa vadeli devlet borçlanma araçlarına yatırım yapan bir fonun veya yapının paylarını blockchain üzerinde token olarak temsil eden ürünlerdir."],["tokenized-stocks","Tokenize hisse senetleri","Tokenize hisse senetleri, bir şirketin hisse senedinin fiyatını takip eden ve genellikle bir saklayıcıda tutulan gerçek hisseyle desteklenen, blockchain üzerinde işlem gören token'lardır."],["tokenized-gold","Tokenize altın","Tokenize altın, her biri belirli miktarda fiziki altına, genellikle bir troy onsa karşılık gelen ve bu altın bir kasada saklanan, blockchain üzerinde transfer edilebilen token'dır."],["stablecoin","Stablecoin (sabit coin)","Stablecoin, değerini genellikle ABD doları gibi bir referans varlığa sabitlemeyi amaçlayan ve kripto piyasasında nakit gibi kullanılan bir kripto paradır."]],"lesson":null,"coin":{"slug":"ondo","name":"Ondo","symbol":"ONDO"},"tool":"/topics/tokenized-assets","cta":false}});
